import numpy as np

def gd_fit(x, y, lr=0.01, steps=5000):
    x, y = np.array(x, dtype=float), np.array(y, dtype=float)
    w, b = 0.0, 0.0
    for _ in range(steps):
        err = w * x + b - y
        w = w - lr * 2 * np.mean(err * x)
    return float(w), float(b)

