def ref(x, y, lr, steps):
    w = b = 0.0
    n = len(x)
    for _ in range(steps):
        e = [w * xi + b - yi for xi, yi in zip(x, y)]
        dw = 2 * sum(ei * xi for ei, xi in zip(e, x)) / n
        db = 2 * sum(e) / n
        w, b = w - lr * dw, b - lr * db
    return w, b
